interface DeliverySink {
  accepted(value: string): void
  rejected(reason: string): void
}
export class Relay {
  connect(engine: Engine, target: DeliverySink): void {
    engine.observe({
      accepted: (value: string) => { target.accepted(value) },
      rejected: (reason: string) => { target.rejected(reason) }
    })
  }
}

